public static boolean isPowerOfThree(int n) {
    if (n <= 0) {
        return false;
    }
    int pow3 = 1;
    while (n > 0) {
        if (n % 3 == 0) {
            n /= 3;
        } else {
            pow3 *= 3;
        }
    }
    return pow3 == n;
}
